#include "darc.h"
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

void darc_catalog_free(DarcCatalog*c){free(c->v);memset(c,0,sizeof*c);}
static int cpush(DarcCatalog*c,const DarcStripe*s){if(c->n==c->cap){size_t nc=c->cap?c->cap*2:16;DarcStripe*v=darc_realloc(c->v,nc*sizeof*v);if(!v)return -1;c->v=v;c->cap=nc;}c->v[c->n++]=*s;return 0;}
int darc_catalog_load(const char*repo,DarcCatalog*c){memset(c,0,sizeof*c);char*p=darc_path_join(repo,"parity/CATALOG");if(!p)return DARC_E_IO;DarcBuf b;if(darc_read_file(p,&b,64u*1024u*1024u)){free(p);return errno==ENOENT?0:DARC_E_CORRUPT;}free(p);if(b.len==9&&!memcmp(b.data,"DARCPAR1\n",9)){darc_buf_free(&b);return 0;}if(b.len<20||memcmp(b.data,"DARPCAT1",8)||darc_rd_u16(b.data+8)!=1||darc_rd_u16(b.data+10)!=0){darc_buf_free(&b);return DARC_E_CORRUPT;}uint64_t n=darc_rd_u64(b.data+12);size_t o=20;for(uint64_t i=0;i<n;i++){if(o+33>b.len)goto bad;DarcStripe s;memset(&s,0,sizeof s);memcpy(s.parity_cid.b,b.data+o,32);o+=32;s.n=b.data[o++];if(s.n<1||s.n>8)goto bad;for(size_t j=0;j<s.n;j++){if(o+40>b.len)goto bad;memcpy(s.m[j].cid.b,b.data+o,32);o+=32;s.m[j].len=darc_rd_u64(b.data+o);o+=8;if(j&&darc_cid_cmp(&s.m[j-1].cid,&s.m[j].cid)>=0)goto bad;}if(cpush(c,&s))goto bad;}if(o+4!=b.len||darc_rd_u32(b.data+o)!=darc_crc32c(b.data,o))goto bad;darc_buf_free(&b);return 0;bad:darc_buf_free(&b);darc_catalog_free(c);return DARC_E_CORRUPT;}
static int stripecmp(const void*a,const void*b){return darc_cid_cmp(&((const DarcStripe*)a)->parity_cid,&((const DarcStripe*)b)->parity_cid);}
int darc_catalog_write(const char*repo,const DarcCatalog*c0){DarcCatalog c=*c0;if(c.n>1)qsort(c.v,c.n,sizeof*c.v,stripecmp);DarcBuf b;darc_buf_init(&b);if(darc_buf_put(&b,"DARPCAT1",8)||darc_buf_u16(&b,1)||darc_buf_u16(&b,0)||darc_buf_u64(&b,(uint64_t)c.n))goto bad;for(size_t i=0;i<c.n;i++){if(darc_buf_put(&b,c.v[i].parity_cid.b,32)||darc_buf_u8(&b,(uint8_t)c.v[i].n))goto bad;for(size_t j=0;j<c.v[i].n;j++)if(darc_buf_put(&b,c.v[i].m[j].cid.b,32)||darc_buf_u64(&b,c.v[i].m[j].len))goto bad;}if(darc_buf_u32(&b,darc_crc32c(b.data,b.len)))goto bad;char*p=darc_path_join(repo,"parity/CATALOG");if(!p)goto bad;int rc=darc_atomic_write(p,b.data,b.len,0644)?DARC_E_IO:0;free(p);darc_buf_free(&b);return rc;bad:darc_buf_free(&b);return DARC_E_IO;}
static int pmcmp(const void*a,const void*b){return darc_cid_cmp(&((const DarcParityMember*)a)->cid,&((const DarcParityMember*)b)->cid);}
int darc_parity_build_payload(const DarcParityMember*m0,size_t n,uint8_t**chunks,DarcBuf*out){if(n<1||n>8)return -1;DarcParityMember m[8];uint8_t*ordered[8]={0};for(size_t i=0;i<n;i++)m[i]=m0[i];qsort(m,n,sizeof m[0],pmcmp);for(size_t i=0;i<n;i++){size_t k=0;for(;k<n;k++)if(darc_cid_eq(&m[i].cid,&m0[k].cid))break;if(k==n)return -1;ordered[i]=chunks[k];}uint64_t mx=0;for(size_t i=0;i<n;i++)if(m[i].len>mx)mx=m[i].len;if(mx>SIZE_MAX)return -1;darc_buf_init(out);if(darc_buf_u16(out,1)||darc_buf_u8(out,(uint8_t)n)||darc_buf_u8(out,0)||darc_buf_u64(out,mx))goto bad;for(size_t i=0;i<n;i++)if(darc_buf_put(out,m[i].cid.b,32)||darc_buf_u64(out,m[i].len))goto bad;if(darc_buf_reserve(out,(size_t)mx))goto bad;size_t base=out->len;memset(out->data+base,0,(size_t)mx);out->len+= (size_t)mx;for(size_t i=0;i<n;i++)for(uint64_t j=0;j<m[i].len;j++)out->data[base+(size_t)j]^=ordered[i][j];return 0;bad:darc_buf_free(out);return -1;}
int darc_parity_parse(const uint8_t*p,size_t n,DarcStripe*s,DarcBuf*pb){memset(s,0,sizeof*s);darc_buf_init(pb);if(n<12||darc_rd_u16(p)!=1||p[3]!=0||p[2]<1||p[2]>8)return -1;s->n=p[2];uint64_t mx=darc_rd_u64(p+4);size_t o=12;for(size_t i=0;i<s->n;i++){if(o+40>n)return -1;memcpy(s->m[i].cid.b,p+o,32);o+=32;s->m[i].len=darc_rd_u64(p+o);o+=8;if(s->m[i].len>mx||(i&&darc_cid_cmp(&s->m[i-1].cid,&s->m[i].cid)>=0))return -1;}if(mx>SIZE_MAX||o+(size_t)mx!=n)return -1;if(darc_buf_put(pb,p+o,(size_t)mx)){darc_buf_free(pb);return -1;}return 0;}
static int protected(const DarcCatalog*c,const DarcCid*cid){for(size_t i=0;i<c->n;i++)for(size_t j=0;j<c->v[i].n;j++)if(darc_cid_eq(cid,&c->v[i].m[j].cid))return 1;return 0;}
int darc_parity_protect_new(const char*repo,const DarcCid*cids,const uint64_t*lens,size_t n,const DarcConfig*cfg){if(!cfg||!cfg->parity_enabled||!n)return 0;DarcCatalog cat;int rc=darc_catalog_load(repo,&cat);if(rc)return rc;DarcParityMember*todo=darc_malloc(n*sizeof*todo);if(!todo){darc_catalog_free(&cat);return DARC_E_IO;}size_t tn=0;for(size_t i=0;i<n;i++)if(!protected(&cat,&cids[i]))todo[tn++]=(DarcParityMember){cids[i],lens[i]};if(tn>1)qsort(todo,tn,sizeof*todo,pmcmp);for(size_t base=0;base<tn;base+=8){size_t k=tn-base<8?tn-base:8;uint8_t*chunks[8]={0};DarcBuf objs[8];memset(objs,0,sizeof objs);for(size_t j=0;j<k;j++){DarcObject o;rc=darc_object_load(repo,&todo[base+j].cid,&o,1);if(rc||o.type!=OBJ_CHUNK){if(!rc)darc_object_free(&o);rc=DARC_E_CORRUPT;goto stripe_fail;}objs[j]=o.payload;o.payload.data=NULL;chunks[j]=objs[j].data;if(objs[j].len!=todo[base+j].len){rc=DARC_E_CORRUPT;goto stripe_fail;}}{DarcBuf pay;if(darc_parity_build_payload(todo+base,k,chunks,&pay)){rc=DARC_E_IO;goto stripe_fail;}DarcCid pc;bool isnew;uint64_t sb;rc=darc_object_store(repo,OBJ_PARITY,pay.data,pay.len,cfg,&pc,&sb,&isnew);darc_buf_free(&pay);if(rc)goto stripe_fail;DarcStripe s;memset(&s,0,sizeof s);s.parity_cid=pc;s.n=k;for(size_t j=0;j<k;j++)s.m[j]=todo[base+j];if(cpush(&cat,&s)){rc=DARC_E_IO;goto stripe_fail;}}
stripe_fail:for(size_t j=0;j<k;j++)darc_buf_free(&objs[j]);if(rc){free(todo);darc_catalog_free(&cat);return rc;}}
 rc=darc_catalog_write(repo,&cat);free(todo);darc_catalog_free(&cat);return rc;}
int darc_chunk_read_or_recover(const char*repo,const DarcCid*cid,DarcBuf*out,bool allow_repair,bool*recovered){if(recovered)*recovered=false;DarcObject o;int rc=darc_object_load(repo,cid,&o,1);if(!rc&&o.type==OBJ_CHUNK){*out=o.payload;o.payload.data=NULL;darc_object_free(&o);return 0;}if(!rc)darc_object_free(&o);DarcCatalog cat;if(darc_catalog_load(repo,&cat))return DARC_E_UNRECOVERABLE;const DarcStripe*st=NULL;size_t miss=0;for(size_t i=0;i<cat.n&&!st;i++)for(size_t j=0;j<cat.v[i].n;j++)if(darc_cid_eq(cid,&cat.v[i].m[j].cid)){st=&cat.v[i];miss=j;break;}if(!st){darc_catalog_free(&cat);return DARC_E_UNRECOVERABLE;}DarcObject po;if(darc_object_load(repo,&st->parity_cid,&po,1)||po.type!=OBJ_PARITY){darc_catalog_free(&cat);return DARC_E_UNRECOVERABLE;}DarcStripe parsed;DarcBuf pb;if(darc_parity_parse(po.payload.data,po.payload.len,&parsed,&pb)){darc_object_free(&po);darc_catalog_free(&cat);return DARC_E_UNRECOVERABLE;}darc_object_free(&po);size_t bad=1;DarcBuf others[8];memset(others,0,sizeof others);for(size_t j=0;j<st->n;j++){if(j==miss)continue;DarcObject co;if(darc_object_load(repo,&st->m[j].cid,&co,1)||co.type!=OBJ_CHUNK){bad++;continue;}others[j]=co.payload;co.payload.data=NULL;darc_object_free(&co);}if(bad!=1){for(size_t j=0;j<st->n;j++)darc_buf_free(&others[j]);darc_buf_free(&pb);darc_catalog_free(&cat);return DARC_E_UNRECOVERABLE;}uint64_t want=st->m[miss].len;if(want>SIZE_MAX||want>pb.len){rc=DARC_E_UNRECOVERABLE;goto done;}darc_buf_init(out);if(darc_buf_put(out,pb.data,(size_t)want)){rc=DARC_E_IO;goto done;}for(size_t j=0;j<st->n;j++)if(j!=miss)for(size_t x=0;x<out->len&&x<others[j].len;x++)out->data[x]^=others[j].data[x];DarcCid got;darc_object_cid(OBJ_CHUNK,out->data,out->len,&got);if(!darc_cid_eq(&got,cid)){darc_buf_free(out);rc=DARC_E_UNRECOVERABLE;goto done;}if(recovered)*recovered=true;rc=0;if(allow_repair){char*p=darc_object_path(repo,cid);if(p){(void)unlink(p);free(p);}DarcConfig c;darc_config_defaults(&c);bool nn;uint64_t sb;int sr=darc_object_store(repo,OBJ_CHUNK,out->data,out->len,&c,&got,&sb,&nn);darc_config_free(&c);if(sr)rc=sr;}
done:for(size_t j=0;j<st->n;j++)darc_buf_free(&others[j]);darc_buf_free(&pb);darc_catalog_free(&cat);return rc;}
